<div class="change-block"><div class="change-block-for" v-for="(item,index) in props.allMes.allMesMy.monsterList" :style="{'background-color':changeIndex === index ? '#f5f5f5' : '#fff'}" @click="clickChange(index)"><div class="change-block-name">{{item.name}}</div><div class="change-block-life">{{item.nowLife}}/{{item.life}}</div><div class="change-block-lv">{{item.level}}</div></div><div style="clear: both;"></div><el-button class="change-button" type="default" @click="cancleChange()">取消</el-button><el-button class="change-button" type="default" :disabled="canChange()" @click="changeMonster()">确认</el-button></div>